TOOLS = {
 'read_status': {'side_effect': False, 'required': {'order_id'}},
 'request_cancellation': {'side_effect': True, 'required': {'order_id', 'idempotency_key'}},
}

def validate_tool_call(name, args, user_permissions):
    if name not in TOOLS: return False, 'unknown tool'
    spec = TOOLS[name]
    if not spec['required'].issubset(args): return False, 'missing arguments'
    if spec['side_effect'] and 'cancel_order' not in user_permissions:
        return False, 'not authorized'
    return True, 'validated; execution still requires policy checks'
